    /// Bloom: gain and Gaussian radius (sigma) of each halo.
    static let bloom: [(gain: Float, radius: Float)] = [(0.467339, 0.0664998), (0.533453, 0.167844), (0.441265, 0.0169478)]

    struct Light {
        var x, y, z, radius, intensity, aspect, angle: Float
        var colour: SIMD3<Float>
    }

    /// The fitted colours with their hues replaced by `palette` (sRGB, cycled over the lights).
    /// Each light keeps its brightness: its brightest channel stays the fitted one's.
    static func colours(for palette: [SIMD3<Float>]) -> [SIMD3<Float>] {
        guard !palette.isEmpty else { return colours }
        return colours.indices.map { k in
            let hue = simd_max(palette[k % palette.count], SIMD3(repeating: 0))
            let peak = hue.max()
            return peak > 1e-4 ? hue * (colours[k].max() / peak) : .zero
        }
    }

    /// The lights at clock time `t` (seconds; the loop repeats every `period`).
    static func blobs(at t: Float, colours: [SIMD3<Float>] = LightModel.colours) -> [Light] {
        let phase = (t.truncatingRemainder(dividingBy: period) + period).truncatingRemainder(dividingBy: period)
        var basis: [Float] = [1]
        for h in 1...4 { basis.append(cos(2 * .pi * Float(h) * phase / period)) }
        for h in 1...4 { basis.append(sin(2 * .pi * Float(h) * phase / period)) }
        return coefficients.enumerated().map { k, light in
            let q = light.map { series in zip(series, basis).reduce(0) { $0 + $1.0 * $1.1 } }
            let radius = exp(q[3])
            return Light(x: q[0], y: q[1], z: q[2], radius: radius, intensity: log1p(exp(q[4])),
                         aspect: max(exp(min(q[5], 0)), minimumWidth / radius), angle: q[6], colour: colours[k])
        }
    }
